import{_ as a,o as n,a as p,b as t}from"./app.C41L12d5.js";const l="/ascendc.github.io/assets/sort32.CkwgUQGL.png",u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"Memory矢量计算","link":"/api/SIMD-API/basic_api/memory_vector_compute/memory_vector_compute"},{"text":"排序组合（ISASI）","link":"/api/SIMD-API/basic_api/memory_vector_compute/sort_and_merge_ISASI/sort_and_merge_ISASI"},{"text":"Sort32","link":"/api/SIMD-API/basic_api/memory_vector_compute/sort_and_merge_ISASI/Sort32"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/memory_vector_compute/sort_and_merge_ISASI/Sort32.md","filePath":"api/SIMD-API/basic_api/memory_vector_compute/sort_and_merge_ISASI/Sort32.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),c={name:"api/SIMD-API/basic_api/memory_vector_compute/sort_and_merge_ISASI/Sort32.md"};function e(o,s,i,r,d,h){return n(),p("div",null,[...s[0]||(s[0]=[t('<div><article class="markdown-body"><h1>Sort32<span id="ZH-CN_TOPIC_0000001487536634"></span></h1><h2 id="产品支持情况">产品支持情况<span id="section1550532418810"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<span id="section618mcpsimp"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_proposal_intf.h&quot;</code></p><p>Sort32接口实现一次迭代内对32个数的降序排列操作。</p><p>如下图所示，src0和src1分别表示待排序的数据score和对应RP的索引index，排序完成后以（score, index）的结构存储在dst中。</p><p>src1固定为uint32_t类型，无论src0是float还是half类型，dst中的（score, index）结构总是占据8B空间。其中：</p><ul><li>当src0为float类型时，dst中的index存储在高4B，score存储在低4B；</li><li>当src0为half类型时，dst中index存储在高4B，score存储在低2B，中间的2B保留。</li></ul><p><strong>图1</strong> Sort32排序示意图</p><p><img src="'+l+`" alt><a id="图1-Sort32排序示意图"></a></p><h2 id="函数原型">函数原型<span id="section620mcpsimp"></span><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Sort32</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src0</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">uint32_t</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src1</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">repeatTime</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<span id="section622mcpsimp"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数数据类型。</td></tr></tbody></table><p><strong>表2</strong> 参数说明</p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>说明</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数。<br> 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT<br> LocalTensor的起始地址需要32字节对齐。</td></tr><tr><td>src0</td><td>输入</td><td>源操作数。<br> 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT<br> LocalTensor的起始地址需要32字节对齐。</td></tr><tr><td>src1</td><td>输入</td><td>源操作数。<br> 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT<br> LocalTensor的起始地址需要32字节对齐。<br> <strong>注：src1的数据类型固定为uint32_t。</strong></td></tr><tr><td>repeatTime</td><td>输入</td><td>重复迭代次数。每次迭代完成32个元素的排序，下次迭代src0跳过128字节空间，src1跳过128字节空间，dst跳过256字节空间。每次迭代输入src0要求128字节对齐，src1要求128字节对齐，输出dst要求256字节对齐。repeatTime∈[0, 255]。</td></tr></tbody></table><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><p><strong>表3</strong> 数据类型组合情况</p><table><thead><tr><th>src0数据类型</th><th>src1数据类型</th><th>dst数据类型</th></tr></thead><tbody><tr><td>half</td><td>uint32_t</td><td>half</td></tr><tr><td>float</td><td>uint32_t</td><td>float</td></tr></tbody></table><h2 id="约束说明">约束说明<span id="section633mcpsimp"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li>地址对齐约束参考<a href="../../../general_description_and_constraints.html">通用地址对齐约束</a>。</li></ul><div data-filter="A3,910b,950"><ul><li>当参数repeatTime取值为0时，该接口的行为如下： <div data-filter="A3,910b"><ul><li>针对如下型号，当参数repeatTime取值为0时，不会执行计算操作，不会对目的操作数进行写入，该接口将被视为NOP（空操作）。 <div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品</li></ul></div></li></ul></div><div data-filter="950"><ul><li>针对Ascend 950PR/Ascend 950DT，该接口通过VF调用<a href="../../reg_vector_compute/reg_vector_compute.html">Reg矢量计算</a>API实现兼容，当参数repeatTime取值为0时，不保证该接口被视为NOP（空操作）。</li></ul></div></li></ul></div><ul><li>如果存在score[i]==score[j]并且i&gt;j，将优先选取score[j]排在前面。</li><li>每次迭代内的数据会进行排序，不同迭代间的数据不会进行排序。</li><li>每次迭代输入src0要求128B(float)/64B(half)对齐，src1要求128B对齐，输出dst要求256B对齐。</li></ul><h2 id="调用示例">调用示例<span id="section642mcpsimp"></span><a class="header-anchor" href="#调用示例">​</a></h2><p>完整示例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_basic_api/01_memory_vector_compute/mrg_sort">Sort32样例</a>。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="w"> </span><span class="n">srcLocal0</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">inQueueSrc0</span><span class="p">.</span><span class="n">DeQue</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="p">();</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">uint32_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">srcLocal1</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">inQueueSrc1</span><span class="p">.</span><span class="n">DeQue</span><span class="o">&lt;</span><span class="kt">uint32_t</span><span class="o">&gt;</span><span class="p">();</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="w"> </span><span class="n">dstLocal</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">outQueueDst</span><span class="p">.</span><span class="n">AllocTensor</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="p">();</span>
<span class="c1">// repeatTime = 4,对128个数分成4组进行排序，每次完成1组32个数的排序</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Sort32</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcLocal0</span><span class="p">,</span><span class="w"> </span><span class="n">srcLocal1</span><span class="p">,</span><span class="w"> </span><span class="mi">4</span><span class="p">);</span>
<span class="n">outQueueDst</span><span class="p">.</span><span class="n">EnQue</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">);</span>
<span class="n">inQueueSrc0</span><span class="p">.</span><span class="n">FreeTensor</span><span class="p">(</span><span class="n">srcLocal0</span><span class="p">);</span>
<span class="n">inQueueSrc1</span><span class="p">.</span><span class="n">FreeTensor</span><span class="p">(</span><span class="n">srcLocal1</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const m=a(c,[["render",e]]);export{u as __pageData,m as default};
